function grid$listcurrentusers(f){
  this.constructor(f);
}
grid$listcurrentusers.prototype = new DirEvent();
grid$listcurrentusers.prototype.afterInit = function(){
	var p = this._dir;

}
grid$listcurrentusers.prototype.beforeButtonGridClick = function(id){
  var p = this._dir;
  var msg1 = ($.lan == 'v')?'Kết thúc phiên làm việc của người dùng: %s': 'Kill instance: %s', msg2 = ($.lan == 'v')?'Không thể kết thúc phiên làm việc của bạn.': 'Not kill your instance.';
  if (id == 'killInstance') {
    var r = p.curr("r");
    if (r != null)
      if ($.userinfo.val('username') == p.val(r, 'username'))
        $.alert(msg2, null, null);
      else
        $.question(msg1.replace('%s', p.val(r, 'username')), null, p, function (q, v) {
          if (v){
            p.grequest(0, 'killInstance', '', 'user_id', function(p0, d){
              if (d != "0") p.deleteRow(r, 0);
            });
          }
          q._close();
        });
    return false;
  }else if (id == 'clearCache') {
    p.request('clearCache', '', null, function(){
      $.clearClientCache();
      $.alert($.msg.get("Processed"), null, null);
    });
    return false
  }else if (id == 'compressAll') {
    p.request('compressAll', '', null, function(){
      $.clearClientCache();
      $.alert($.msg.get("Processed"), null, null);
    });
  }
  return true
}

